// The nine works shown on the site, taken from the shared works data
// (js/data/works.js, generated by tools/build_works.py). No categories:
// each opens straight into its own project page.
import { WORKS } from './data/works.js';

const PICK = [
  ['ui', 'oaks-dashboard', 'UI / UX · Dashboard'],
  ['brand', 'gaurav', 'Brand & Packaging'],
  ['game', 'elixir', 'Game Art'],
  ['ui', 'coldtrace', 'Product Design'],
  ['art', 'p7', 'Logo & Print'],
  ['brand', 'momma', 'Packaging System'],
  ['social', 'ergon', 'Social Media'],
  ['ui', 'ergonxlu', 'Web Design'],
  ['art', 'fibril', 'Packaging & Print'],
];

const fix = (src) => src;   // works.js paths are already relative to the site root

export const PROJECTS = PICK.map(([cat, id, kind], i) => {
  const w = WORKS[cat].find((x) => x.id === id);
  const images = (w.images || []).map((im) => ({ ...im, src: fix(im.src), thumb: fix(im.thumb) }));
  const meta = w.meta || [w.industry, ...(w.deliverables || [])].filter(Boolean);
  return {
    id,
    no: String(i + 1).padStart(2, '0'),
    title: w.title || w.name,
    kind,
    sub: w.sub || w.tagline || kind,
    desc: w.desc || `${w.sub || ''}: a selection of posts and campaign creatives.`,
    meta: meta.slice(0, 4),
    live: w.live ? fix(w.live) : null,
    liveLabel: w.kind === 'site' ? 'Visit the live site' : 'Open the live prototype',
    images,
    cover: images[0],
  };
});
